// Plan Gmail Searches
// Builds Gmail searches for the addresses you pitched: what you sent, and what they replied.
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

// ---- places.js ----

// Collects every string inside an error payload. n8n stores API errors in different shapes
// ({message: '403 - "{...}"'}, {error: '{"error":{...}}', statusCode}, {description}), so checks run on all of it.
function errorText(err) {
  const parts = [];
  const walk = (v, depth) => {
    if (v === null || v === undefined || depth > 4) return;
    if (typeof v === 'string') {
      parts.push(v.replace(/\\"/g, '"'));
      return;
    }
    if (typeof v !== 'object') return;
    for (const k of ['message', 'description', 'error', 'status', 'statusText', 'body', 'details']) if (k in v) walk(v[k], depth + 1);
  };
  walk(err, 0);
  return parts.join(' | ');
}

// The most useful single message inside an error payload (the API's own message when present).
function errorSummary(err) {
  const text = errorText(err);
  const m = text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) return m[1];
  const e = err || {};
  return str(typeof e === 'string' ? e : e.message || e.description || text).slice(0, 300);
}

// ---- sheet.js ----

const STATUS = {
  NEW: 'New',
  PITCH_READY: 'Pitch ready',
  DRAFT_READY: 'Draft ready',
  CONTACTED: 'Contacted',
  FOLLOW_UP_DRAFTED: 'Follow-up drafted',
  REPLIED: 'Replied',
  MEETING: 'Meeting booked',
  WON: 'Won',
  LOST: 'Lost',
  DO_NOT_CONTACT: 'Do not contact',
};

// Statuses after which the follow-up workflow must never email the business again.
const FINAL_STATUSES = [STATUS.REPLIED, STATUS.MEETING, STATUS.WON, STATUS.LOST, STATUS.DO_NOT_CONTACT, 'Not interested', 'Bounced'];

// ---- followup.js ----

const EMAIL_RE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,24}/gi;

function emailsIn(header) {
  return (str(header).match(EMAIL_RE) || []).map((e) => e.toLowerCase());
}

function candidateRows(rows) {
  return (rows || []).filter((r) => {
    const email = emailsIn(r && r.Email)[0];
    const status = str(r && r.Status);
    return email && str(r['Place ID']) && !FINAL_STATUSES.some((s) => s.toLowerCase() === status.toLowerCase());
  });
}

// One Gmail search per chunk of addresses, for sent mail and for replies.
function buildGmailQueries(rows, options) {
  const opts = options || {};
  const lookbackDays = int(opts.lookbackDays, 120) || 120;
  const chunkSize = int(opts.chunkSize, 25) || 25;
  const emails = [...new Set(candidateRows(rows).map((r) => emailsIn(r.Email)[0]))];
  const queries = [];
  for (let i = 0; i < emails.length; i += chunkSize) {
    const chunk = emails.slice(i, i + chunkSize);
    queries.push({ kind: 'sent', q: `in:sent newer_than:${lookbackDays}d {${chunk.map((e) => `to:${e}`).join(' ')}}` });
    queries.push({ kind: 'reply', q: `-in:sent -in:drafts newer_than:${lookbackDays}d {${chunk.map((e) => `from:${e}`).join(' ')}}` });
  }
  return queries;
}

// ---- steps.js ----

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

function isSheetUrl(url) {
  return /^https:\/\/docs\.google\.com\/spreadsheets\/d\/[a-zA-Z0-9_-]{20,}/.test(str(url));
}

function stepPlanGmailSearches(rows, settings) {
  const valid = (rows || []).filter((r) => r && Object.keys(r).length);
  const sheetError = valid.find((r) => r.error);
  if (sheetError) return [stop("Couldn't read your Google Sheet", errorSummary(sheetError.error), true)];
  if (!isSheetUrl(settings && settings.googleSheetUrl)) return [stop('Settings needed', 'Paste your Client Finder Google Sheet URL into googleSheetUrl in the "⚙️ Settings" node.', true)];
  const queries = buildGmailQueries(valid);
  if (!queries.length) return [stop('Nothing to follow up', 'No leads with an email address are waiting for a reply.')];
  return queries;
}

// ---- this step ----
const job = $('Prepare Follow-ups').first().json;
const rows = $input.all().map((i) => i.json);
return stepPlanGmailSearches(rows, job.settings).map((json) => ({ json }));

// Decide Follow-ups
// Replied → mark Replied. Sent and quiet for long enough → draft a follow-up. Draft not sent yet → wait.
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

function isoDate(value) {
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
}

// Parses dates written by people or by Google Sheets ("2026-10-06", "10/6/2026", "2026-10-06T09:00:00Z").
function parseDate(value) {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  if (typeof value === 'number' && Number.isFinite(value)) {
    // Google Sheets serial day number (days since 1899-12-30) or epoch milliseconds.
    if (value > 20000 && value < 80000) return new Date(Math.round((value - 25569) * 86400000));
    if (value > 1e11) return new Date(value);
    return null;
  }
  const s = str(value);
  if (!s) return null;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return new Date(s + 'T00:00:00Z');
  const us = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (us) return new Date(Date.UTC(Number(us[3]), Number(us[1]) - 1, Number(us[2])));
  if (/^\d+(\.\d+)?$/.test(s)) return parseDate(Number(s));
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d;
}

function daysBetween(from, to) {
  return Math.floor((to.getTime() - from.getTime()) / 86400000);
}

// ---- sheet.js ----

const STATUS = {
  NEW: 'New',
  PITCH_READY: 'Pitch ready',
  DRAFT_READY: 'Draft ready',
  CONTACTED: 'Contacted',
  FOLLOW_UP_DRAFTED: 'Follow-up drafted',
  REPLIED: 'Replied',
  MEETING: 'Meeting booked',
  WON: 'Won',
  LOST: 'Lost',
  DO_NOT_CONTACT: 'Do not contact',
};

// Statuses after which the follow-up workflow must never email the business again.
const FINAL_STATUSES = [STATUS.REPLIED, STATUS.MEETING, STATUS.WON, STATUS.LOST, STATUS.DO_NOT_CONTACT, 'Not interested', 'Bounced'];

// ---- followup.js ----

const EMAIL_RE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,24}/gi;

function emailsIn(header) {
  return (str(header).match(EMAIL_RE) || []).map((e) => e.toLowerCase());
}

function parseFollowUpDays(value) {
  const days = str(value)
    .split(/[,;\s]+/)
    .map((x) => int(x, 0))
    .filter((x) => x > 0 && x < 120);
  return days.length ? days : [3, 7];
}

function candidateRows(rows) {
  return (rows || []).filter((r) => {
    const email = emailsIn(r && r.Email)[0];
    const status = str(r && r.Status);
    return email && str(r['Place ID']) && !FINAL_STATUSES.some((s) => s.toLowerCase() === status.toLowerCase());
  });
}

function messageTime(m) {
  const ms = int(m && m.internalDate, 0);
  if (ms > 0) return new Date(ms);
  return parseDate(m && (m.date || m.Date));
}

function isSentMessage(m) {
  const labels = (m && (m.labels || m.labelIds)) || [];
  return labels.some((l) => (typeof l === 'string' ? l : l && (l.id || l.name)) === 'SENT');
}

// messages = simplified Gmail messages (From, To, Cc, internalDate, labels, threadId).
function indexGmail(messages, leadEmails) {
  const wanted = new Set((leadEmails || []).map((e) => e.toLowerCase()));
  const sent = {};
  const replies = {};
  for (const m of messages || []) {
    if (!m || m.error) continue;
    const t = messageTime(m);
    if (!t) continue;
    const from = emailsIn(m.From)[0] || '';
    if (wanted.has(from) && !isSentMessage(m)) {
      const r = replies[from] || (replies[from] = { first: t, last: t });
      if (t < r.first) r.first = t;
      if (t > r.last) r.last = t;
      continue;
    }
    if (isSentMessage(m) || !wanted.has(from)) {
      for (const to of [...emailsIn(m.To), ...emailsIn(m.Cc)]) {
        if (!wanted.has(to)) continue;
        const s = sent[to] || (sent[to] = { first: t, last: t, threadId: str(m.threadId) });
        if (t < s.first) s.first = t;
        if (t > s.last) {
          s.last = t;
          s.threadId = str(m.threadId) || s.threadId;
        }
      }
    }
  }
  return { sent, replies };
}

function startOfUtcDay(d) {
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}

// Returns one action per lead that needs a change: { action, row, update, followUpNumber, email, threadId }.
function decideFollowUps(rows, gmailIndex, settings, now) {
  const s = settings || {};
  const today = now || new Date();
  const gaps = parseFollowUpDays(s.followUpDays);
  const maxFollowUps = Math.max(0, Math.min(5, int(s.maxFollowUps, gaps.length)));
  const idx = gmailIndex || { sent: {}, replies: {} };
  const actions = [];
  for (const row of candidateRows(rows)) {
    const email = emailsIn(row.Email)[0];
    const status = str(row.Status);
    const sentInfo = idx.sent[email];
    const sheetContacted = parseDate(row['Last Contacted']);
    let lastSent = sentInfo ? sentInfo.last : null;
    if (sheetContacted && (!lastSent || sheetContacted > lastSent)) lastSent = sheetContacted;
    const firstSent = sentInfo ? sentInfo.first : sheetContacted;
    const reply = idx.replies[email];
    const base = { 'Place ID': str(row['Place ID']) };
    const contactedIso = lastSent ? isoDate(lastSent) : '';

    if (reply && firstSent && reply.last >= firstSent) {
      actions.push({ action: 'replied', row, email, update: Object.assign(base, { Status: STATUS.REPLIED, 'Last Contacted': contactedIso }) });
      continue;
    }
    if (!lastSent) continue; // the first email was never sent: nothing to follow up yet

    const followUps = Math.max(0, int(row['Follow-ups'], 0));
    const lastDraft = parseDate(row['Last Draft On']);
    const draftWaiting = Boolean(lastDraft && lastDraft > startOfUtcDay(lastSent));
    const needsContactedStatus = [STATUS.DRAFT_READY, STATUS.PITCH_READY, STATUS.FOLLOW_UP_DRAFTED, STATUS.NEW, ''].includes(status) && !draftWaiting;
    const gap = gaps[Math.min(followUps, gaps.length - 1)];
    const due = followUps < maxFollowUps && !draftWaiting && daysBetween(lastSent, today) >= gap;

    if (due) {
      // Prefer the thread of the email that was really sent (it surely exists); fall back to the sheet's draft thread.
      const threadId = (sentInfo && sentInfo.threadId) || str(row['Thread ID']) || '';
      actions.push({
        action: 'follow-up',
        row,
        email,
        threadId,
        followUpNumber: followUps + 1,
        update: Object.assign(base, {
          Status: STATUS.FOLLOW_UP_DRAFTED,
          'Follow-ups': followUps + 1,
          'Last Draft On': isoDate(today),
          'Last Contacted': contactedIso,
          'Thread ID': threadId,
        }),
      });
    } else if (needsContactedStatus || (contactedIso && str(row['Last Contacted']) !== contactedIso && !draftWaiting)) {
      actions.push({ action: 'contacted', row, email, update: Object.assign(base, { Status: STATUS.CONTACTED, 'Last Contacted': contactedIso }) });
    }
  }
  return actions;
}

// ---- steps.js ----

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

function stepDecideFollowUps(rows, messages, settings, now) {
  const valid = (rows || []).filter((r) => r && !r.error && Object.keys(r).length);
  const emails = candidateRows(valid).map((r) => emailsIn(r.Email)[0]);
  const index = indexGmail((messages || []).filter((m) => m && !m.error && m.id), emails);
  const actions = decideFollowUps(valid, index, settings, now || new Date());
  if (!actions.length) return [stop('Nothing to do today', 'No follow-ups are due and no statuses changed.')];
  return actions.map((a) => ({
    action: a.action,
    email: a.email,
    threadId: a.threadId || '',
    followUpNumber: a.followUpNumber || 0,
    row: a.row,
    update: a.update,
  }));
}

// ---- this step ----
const job = $('Prepare Follow-ups').first().json;
const rows = $('Read Leads').all().map((i) => i.json);
const messages = $input.all().map((i) => i.json);
return stepDecideFollowUps(rows, messages, job.settings, new Date()).map((json) => ({ json }));

// Build Follow-up Request
// Asks Claude for a short follow-up based on the original pitch.
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function truncate(s, max) {
  const t = str(s);
  return t.length <= max ? t : t.slice(0, Math.max(0, max - 1)).trimEnd() + '…';
}

// ---- ai.js ----

const ANTHROPIC_VERSION = '2023-06-01';

const DEFAULT_MODEL = 'claude-opus-5-5';

const FALLBACK_BETA = 'server-side-fallback-2026-07-01';

// What each model accepts. Unknown models get the safest request shape (no effort, no fallbacks,
// JSON requested through the prompt instead of structured outputs).
const MODEL_CAPS = {
  'claude-fable-5-1': { effort: true, fallbacks: true, structured: true },
  'claude-fable-5': { effort: true, fallbacks: false, structured: true },
  'claude-opus-5-5': { effort: true, fallbacks: true, structured: true },
  'claude-opus-5': { effort: true, fallbacks: true, structured: true },
  'claude-opus-4-8': { effort: true, fallbacks: false, structured: true },
  'claude-sonnet-5-5': { effort: true, fallbacks: true, structured: true },
  'claude-sonnet-5': { effort: true, fallbacks: false, structured: true },
  'claude-haiku-4-5': { effort: false, fallbacks: false, structured: true },
};

const EFFORT_LEVELS = ['low', 'medium', 'high', 'xhigh', 'max'];

function modelCaps(model) {
  return MODEL_CAPS[model] || { effort: false, fallbacks: false, structured: false };
}

const FOLLOWUP_SCHEMA = {
  type: 'object',
  properties: {
    email_body: { type: 'string', description: 'The follow-up email body without signature or sign-off.' },
  },
  required: ['email_body'],
  additionalProperties: false,
};

function settingsOf(s) {
  const x = s || {};
  return {
    senderName: str(x.yourName),
    senderBusiness: str(x.yourBusinessName),
    senderWebsite: str(x.yourWebsite),
    senderPhone: str(x.yourPhone),
    senderAddress: str(x.yourAddress),
    service: str(x.yourService),
    offer: str(x.yourOffer),
    language: str(x.emailLanguage) || 'English',
    tone: str(x.emailTone) || 'friendly, direct and human',
    maxWords: Math.min(200, Math.max(50, Number(x.maxEmailWords) || 110)),
    model: str(x.aiModel) || DEFAULT_MODEL,
    effort: EFFORT_LEVELS.includes(str(x.aiEffort).toLowerCase()) ? str(x.aiEffort).toLowerCase() : 'low',
    optOutLine: str(x.optOutLine),
  };
}

function senderText(s) {
  const lines = ['About the sender:'];
  if (s.senderName) lines.push(`Name: ${s.senderName}`);
  if (s.senderBusiness) lines.push(`Business: ${s.senderBusiness}`);
